 @GET public Map<String,Object> view(){var f=new LinkedHashMap<>(session.frame());f.put("model",System.getProperty("ghost.model",System.getenv().getOrDefault("GHOST_MODEL","tev1:0.8b")));return f;}
 @POST public Uni<Map<String,Object>> reset(NewGame request){int level=request.level()==0?1:request.level();RunState r;try{r=session.reset(request.seed(),level,request.singleLevel()?level:3);}catch(IllegalArgumentException e){throw new BadRequestException(e.getMessage());}return execute(r).replaceWith(this::view);}
 @POST @Path("/actions") public Uni<Map<String,Object>> action(Action action){if(!Rules.ACTIONS.contains(action.action()))throw new BadRequestException("Unknown action");RunState r=admit("HUMAN",action.action(),action.revision(),1,120000);return execute(r).replaceWith(this::view);}
