package dev.ghost;
import io.quarkus.test.junit.QuarkusTest;
import jakarta.inject.Inject;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfSystemProperty;
import static io.restassured.RestAssured.given;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;

@QuarkusTest
class GhostRecordingE2ETest {
 @Inject Session session;
 private void reset(long seed,int level,boolean single){given().contentType("application/json").body(Map.of("seed",seed,"level",level,"singleLevel",single)).post("/api/game").then().statusCode(200);}
 private void action(String a){given().contentType("application/json").body(Map.of("action",a,"revision",session.latest().revision())).post("/api/game/actions").then().statusCode(200);}
 private void play(String player,int limit,long millis){given().contentType("application/json").body(Map.of("player",player,"revision",session.latest().revision(),"maxDecisions",limit,"durationMs",millis)).post("/api/game/play").then().statusCode(200);}
 private void waitForPlayer() throws Exception {long deadline=System.nanoTime()+125_000_000_000L;while(session.active()&&System.nanoTime()<deadline)Thread.sleep(30);assertFalse(session.active());}
 @Test void ghostRecordingE2ECompletesHumanCampaignThenBoundedExplorer() throws Exception {
  reset(1983,1,false);
  for(int level=1;level<=3;level++)for(String a:Rules.witness(session.latest().game()))action(a);
  assertEquals("WON",session.latest().game().status());assertEquals(3,session.latest().game().exitsFound());
  reset(1983,1,true);play("EXPLORER",128,120000);waitForPlayer();assertEquals("WON",session.latest().game().status());assertTrue(session.latest().decisions()<=128);
