    map.fillRect(x + 2, y + 2, c - 4, c - 4);
    for (let d = 0; d < 4; d++) {
      if (edges[d] === ".") continue;
      map.strokeStyle =
        edges[d] === "E" ? "#ff71c5" : edges[d] === "?" ? "#3a4854" : "#72bfb7";
      map.lineWidth = edges[d] === "E" ? 3 : 1;
      map.setLineDash(edges[d] === "?" ? [2, 3] : []);
      map.beginPath();
      if (d === 0) {
