        map.lineTo(x + c, y);
      }
      if (d === 1) {
        map.moveTo(x + c, y);
        map.lineTo(x + c, y + c);
      }
      if (d === 2) {
        map.moveTo(x, y + c);
        map.lineTo(x + c, y + c);
      }
      if (d === 3) {
        map.moveTo(x, y);
        map.lineTo(x, y + c);
      }
      map.stroke();
      map.setLineDash([]);
