function draw(o, yaw = o.direction * Math.PI / 2, turnLabel = "") {
  const W = 960, H = 600, focal = 200, halfHeight = 0.6;
  ctx.fillStyle = "#050e1b";
  ctx.fillRect(0, 0, W, H);
