      const t = (0.05 - a[2]) / (b[2] - a[2]);
      a = a.map((v, j) => v + (b[j] - v) * t);
    } else if (b[2] < 0.05) {
      const t = (0.05 - b[2]) / (a[2] - b[2]);
      b = b.map((v, j) => v + (a[j] - v) * t);
    }
    line(...project(a), ...project(b), color, width);
  }
  face([[-1, halfHeight, -1], [1, halfHeight, -1], [1, halfHeight, 1], [-1, halfHeight, 1]], "#08111d", "#30505c");
  face([[-1, -halfHeight, -1], [1, -halfHeight, -1], [1, -halfHeight, 1], [-1, -halfHeight, 1]], "#11182a", "#38606e");
  for (let v = -1; v <= 1.01; v += 0.25) {
