#!/usr/bin/env python3
"""Check that saved-result pairing fails closed, including under python -O."""
import copy
import json
from pathlib import Path
import subprocess
import sys
import tempfile
import unittest

REPO = Path(__file__).resolve().parents[1]


class ComparisonValidation(unittest.TestCase):
    def run_pair(self, mutate=None):
        small = json.loads((REPO / 'evidence/comparison-08b-compact.json').read_text())
        large = json.loads((REPO / 'evidence/comparison-4b-compact.json').read_text())
        if mutate:
            mutate(large)
        with tempfile.TemporaryDirectory() as directory:
            root = Path(directory)
            for name, value in [('small', small), ('large', large)]:
                (root / (name + '.json')).write_text(json.dumps(value))
            result = subprocess.run([sys.executable, '-O', str(REPO / 'scripts/compare-models.py'),
                                     str(root / 'small.json'), str(root / 'large.json'), '--out', str(root / 'out.json')],
                                    capture_output=True, text=True)
            return result.returncode, (root / 'out.json').exists()

    def test_actual_saved_pair_passes(self):
        self.assertEqual((0, True), self.run_pair())

    def test_different_observation_rejected(self):
        self.assertNotEqual((0, True), self.run_pair(lambda r: r['trials'][0]['initialObservation'].update(facing='S')))

    def test_different_source_rejected(self):
        self.assertNotEqual((0, True), self.run_pair(lambda r: r['sourceSha256'].update(changed='yes')))

    def test_different_budget_rejected(self):
        self.assertNotEqual((0, True), self.run_pair(lambda r: r.update(maxDecisions=129)))

    def test_duplicate_case_rejected(self):
        self.assertNotEqual((0, True), self.run_pair(lambda r: r['trials'].__setitem__(1, copy.deepcopy(r['trials'][0]))))

    def test_execution_failure_rejected(self):
        self.assertNotEqual((0, True), self.run_pair(lambda r: r['trials'][0].update(executionFailure=True)))


if __name__ == '__main__':
    unittest.main()

