package dev.ghost;

import java.util.*;

public final class Runs {
  private Runs() {}

  public static RunState create(
      GameState g,
      String generation,
      long revision,
      String player,
      String action,
      int limit,
      long millis) {
    long now = System.nanoTime();
    return new RunState(
        g,
        generation,
        UUID.randomUUID().toString(),
        revision,
        player,
        action,
        0,
        limit,
        now + millis * 1_000_000,
        now,
        now,
        "",
        List.of(g.room()),
        List.of());
  }

  public static RunState control(RunState r, long now, String reason) {
    return new RunState(
        r.game(),
        r.generation(),
        r.segment(),
        r.revision(),
        r.player(),
        r.action(),
        r.decisions(),
        r.maxDecisions(),
        r.deadline(),
        now,
        now,
        reason,
        r.stack(),
        r.log());
  }

  public static String endReason(RunState r) {
    if (!r.stopReason().isEmpty()) return r.stopReason();
    if (!r.game().status().equals("PLAYING")) return r.game().status();
    if (r.decisions() >= r.maxDecisions()) return "DECISION_LIMIT";
    if (r.observedAt() >= r.deadline()) return "TIME_LIMIT";
    return "";
  }

  public static RunState apply(ActionTurn t) {
    RunState r = t.run();
    GameState g = Rules.act(r.game(), t.action());
    List<ActionLog> log = new ArrayList<>(r.log());
    log.add(
        new ActionLog(
            r.decisions() + 1,
            r.game().level(),
            r.game().room(),
            r.game().direction(),
            t.action(),
            g.message(),
            t.latencyMs(),
            r.player()));
    return new RunState(
        g,
        r.generation(),
        r.segment(),
        r.revision() + 1,
        r.player(),
        t.action(),
        r.decisions() + (t.action().equals("START") ? 0 : 1),
        r.maxDecisions(),
        r.deadline(),
        r.observedAt(),
        r.decisionStarted(),
        "",
        Baselines.advanceStack(r, g),
        log);
  }
}
package dev.ghost;

import jakarta.enterprise.context.ApplicationScoped;
import java.util.*;

/** One local host session; gameplay transitions enter through the publish Command. */
@ApplicationScoped
public class Session {
  private RunState latest;
  private String generation = "", owner = "", reason = "READY";
  private boolean paused;
  private final List<ActionLog> history = new ArrayList<>();

  public synchronized RunState reset(long seed, int level, int last) {
    GameState initial = Rules.newGame(seed, level, last);
    generation = UUID.randomUUID().toString();
    latest = Runs.create(initial, generation, 0, "HUMAN", "START", 1, 120000);
    owner = latest.segment();
    paused = false;
    reason = "READY";
    history.clear();
    return latest;
  }

  public synchronized RunState admit(
      String player, String action, long revision, int limit, long millis) {
    if (latest == null) throw new IllegalArgumentException("Start a game first");
    if (!owner.isEmpty()) throw new IllegalStateException("A player already owns this turn");
    if (revision != latest.revision())
      throw new IllegalStateException("Stale revision; refresh the game");
    if (!latest.game().status().equals("PLAYING"))
      throw new IllegalStateException("Start a new game");
    latest = Runs.create(latest.game(), generation, revision, player, action, limit, millis);
    owner = latest.segment();
    paused = false;
    reason = "PLAYING";
    return latest;
  }

  public synchronized RunState control(RunState r) {
    String stop =
        !generation.equals(r.generation()) || !owner.equals(r.segment())
            ? "SUPERSEDED"
            : paused ? "PAUSED" : "";
    return Runs.control(r, System.nanoTime(), stop);
  }

  public synchronized RunState publish(RunState r) {
    if (!generation.equals(r.generation()) || !owner.equals(r.segment()))
      throw new IllegalStateException("stale-segment");
    if (r.revision() == latest.revision() && r.equals(latest)) return r;
    if (r.revision() != latest.revision() + 1) throw new IllegalStateException("stale-revision");
    latest = r;
    if (!r.log().isEmpty()) history.add(r.log().getLast());
    return r;
  }

  public synchronized void finish(String segment, String result) {
    if (owner.equals(segment)) {
      owner = "";
      reason = result;
      paused = false;
    }
  }

  public synchronized void pause() {
    if (!owner.isEmpty()) {
      paused = true;
      reason = "PAUSING";
    }
  }

  public synchronized boolean active() {
    return !owner.isEmpty();
  }

  public synchronized RunState latest() {
    return latest;
  }

  public synchronized List<ActionLog> history() {
    return List.copyOf(history);
  }

  public synchronized Map<String, Object> frame() {
    if (latest == null) return Map.of("ready", false, "active", false);
    GameState g = latest.game();
    var f = new LinkedHashMap<String, Object>();
    f.put("ready", true);
    f.put("generation", generation);
    f.put("segment", latest.segment());
    f.put("seed", g.seed());
    f.put("revision", latest.revision());
    f.put("observation", Observations.view(g));
    f.put("level", g.level());
    f.put("status", g.status());
    f.put("message", g.message());
    f.put("active", !owner.isEmpty());
    f.put("pausing", paused);
    f.put("reason", reason);
    f.put("player", latest.player());
    f.put("moves", g.moves());
    f.put("actions", g.actions());
    f.put("collisions", g.collisions());
    f.put("repeats", g.repeats());
    f.put("explored", g.explored());
    f.put("exitsFound", g.exitsFound());
    f.put("decisions", latest.decisions());
    f.put("latestAction", g.lastAction());
    f.put("latencyMs", latest.log().isEmpty() ? 0 : latest.log().getLast().latencyMs());
    return f;
  }
}
package dev.ghost;

import io.smallrye.mutiny.Uni;
import jakarta.enterprise.context.ApplicationScoped;
import org.pipelineframework.service.ReactiveService;

@ApplicationScoped
public class ChooseTurn implements ReactiveService<RunState, NextTurn> {
  public Uni<NextTurn> process(RunState r) {
    return Uni.createFrom().item(() -> transform(r));
  }

  private NextTurn transform(RunState r) {
    String end = Runs.endReason(r);
    if (!end.isEmpty()) return new NextTurn.Done(new RunResult(r, end));
    if (r.player().equals("TEV1"))
      return new NextTurn.Model(new ModelTurn(r, Observations.request(r.game())));
    if (r.player().equals("TEV1_4B"))
      return new NextTurn.Large(new LargeModelTurn(r, Observations.request(r.game())));
    String action =
        r.player().equals("HUMAN")
            ? r.action()
            : Baselines.choose(r.game(), r.player(), r.decisions(), r.stack());
    return new NextTurn.Action(new ActionTurn(r, action, 0));
  }
}
package dev.ghost;

import io.smallrye.mutiny.*;
import jakarta.inject.Inject;
import jakarta.ws.rs.*;
import jakarta.ws.rs.core.MediaType;
import java.time.Duration;
import java.util.*;
import org.jboss.resteasy.reactive.RestStreamElementType;
import org.pipelineframework.PipelineExecutionService;
import org.pipelineframework.execution.*;

@Path("/api/game")
@Produces(MediaType.APPLICATION_JSON)
public class GameResource {
  @Inject Session session;
  @Inject PipelineExecutionService pipelines;
  @Inject ModelSettings settings;

  public record NewGame(long seed, int level, boolean singleLevel) {}

  public record Action(String action, long revision) {}

  public record Play(String player, long revision, Integer maxDecisions, Long durationMs) {}

  @GET
  public Map<String, Object> view() {
    var f = new LinkedHashMap<>(session.frame());
    f.put("model", settings.model(f.getOrDefault("player", "TEV1").toString()));
    f.put("models", settings.models());
    return f;
  }

  @POST
  public Uni<Map<String, Object>> reset(NewGame request) {
    if (request == null) throw new BadRequestException("Game request is required");
    int level = request.level() == 0 ? 1 : request.level();
    RunState r;
    try {
      r = session.reset(request.seed(), level, request.singleLevel() ? level : 3);
    } catch (IllegalArgumentException e) {
      throw new BadRequestException(e.getMessage());
    }
    return execute(r).replaceWith(this::view);
  }

  @POST
  @Path("/actions")
  public Uni<Map<String, Object>> action(Action action) {
    if (action == null || action.action() == null || !Rules.ACTIONS.contains(action.action()))
      throw new BadRequestException("Unknown action");
    RunState r = admit("HUMAN", action.action(), action.revision(), 1, 120000);
    return execute(r).replaceWith(this::view);
  }

  @POST
  @Path("/play")
  public Map<String, Object> play(Play p) {
    if (p == null
        || p.player() == null
        || !List.of("TEV1", "TEV1_4B", "RANDOM", "EXPLORER").contains(p.player()))
      throw new BadRequestException("Unknown player");
    int limit = p.maxDecisions() == null ? 128 : p.maxDecisions();
    long millis = p.durationMs() == null ? 120000 : p.durationMs();
    if (limit < 1 || limit > 128 || millis < 1 || millis > 120000)
      throw new BadRequestException("Budget exceeds demo bounds");
    RunState r = admit(p.player(), "", p.revision(), limit, millis);
    execute(r).subscribe().with(done -> {}, error -> {});
    return view();
  }

  @POST
  @Path("/pause")
  public Map<String, Object> pause() {
    session.pause();
    return view();
  }

  @GET
  @Path("/history")
  public List<ActionLog> history() {
    return session.history();
  }

  @GET
  @Path("/events")
  @Produces(MediaType.SERVER_SENT_EVENTS)
  @RestStreamElementType(MediaType.APPLICATION_JSON)
  public Multi<Map<String, Object>> events() {
    return Multi.createFrom()
        .ticks()
        .every(Duration.ofMillis(150))
        .onOverflow()
        .drop()
        .map(t -> view());
  }

  private RunState admit(String player, String action, long revision, int limit, long duration) {
    try {
      return session.admit(player, action, revision, limit, duration);
    } catch (IllegalArgumentException | IllegalStateException e) {
      throw new ClientErrorException(e.getMessage(), 409);
    }
  }

  /** This is the sole external root-admission boundary. Internal turns never re-enter it. */
  private Uni<RunResult> execute(RunState r) {
    String execution = UUID.randomUUID().toString();
    return Uni.createFrom()
        .<RunResult>emitter(
            emitter -> {
              PipelineExecutionContextHolder.set(
                  new PipelineExecutionContext("local-demo", execution, 0));
              try {
                var subscription =
                    pipelines
                        .<RunResult>executePipelineUnary(Uni.createFrom().item(r))
                        .ifNoItem()
                        .after(
                            Duration.ofMillis(
                                Math.max(1, (r.deadline() - System.nanoTime()) / 1_000_000)))
                        .fail()
                        .invoke(result -> session.finish(r.segment(), result.reason()))
                        .onFailure()
                        .invoke(
                            failure ->
                                session.finish(
                                    r.segment(),
                                    failure instanceof io.smallrye.mutiny.TimeoutException
                                            || failure
                                                instanceof java.util.concurrent.TimeoutException
                                        ? "TIME_LIMIT"
                                        : "PROVIDER_OR_PIPELINE_FAILURE: "
                                            + failure.getClass().getSimpleName()))
                        .subscribe()
                        .with(emitter::complete, emitter::fail);
                emitter.onTermination(subscription::cancel);
              } finally {
                PipelineExecutionContextHolder.clear();
              }
            });
  }
}
