pipelines:
  play:
    input: RunState
    output: RunResult
    steps:
      - name: Observe control and time
        kind: query
        using: game
        operation: control
        operationVersion: 1
        input: RunState
        output: RunState
        cardinality: ONE_TO_ONE
        java: { input: dev.ghost.RunState, output: dev.ghost.RunState }
      - name: Choose turn branch
        service: dev.ghost.ChooseTurn
        input: RunState
        output: NextTurn
        cardinality: ONE_TO_ONE
        java: { input: dev.ghost.RunState, output: dev.ghost.NextTurn }
      - name: Ask Tev1
        # The prompt is question.instructions inside the typed DecisionRequest below.
        # Authority: dev.ghost.Observations.ACTION_PROMPT and optional CLUE_PROMPT.
        # ChooseTurn supplies the same question/criteria to both model bindings.
        kind: query
        using: model
        operation: decide
        operationVersion: 1
        input: ModelTurn
        output: Chosen
        cardinality: ONE_TO_ONE
        java: { input: dev.ghost.ModelTurn, output: dev.ghost.Chosen }
        config:
          request: request
          completion: { field: result, run: run }
      - name: Ask Tev1 4B
        # Same action-focused typed prompt as Ask Tev1; only the model binding differs.
        kind: query
        using: model4b
        operation: decide
        operationVersion: 1
        input: LargeModelTurn
        output: Chosen
        cardinality: ONE_TO_ONE
        java: { input: dev.ghost.LargeModelTurn, output: dev.ghost.Chosen }
        config:
          request: request
          completion: { field: result, run: run }
      - name: Validate model choice
        service: dev.ghost.DecodeChoice
        input: Chosen
        output: ActionTurn
        cardinality: ONE_TO_ONE
        java: { input: dev.ghost.Chosen, output: dev.ghost.ActionTurn }
      - name: Shared action
        service: dev.ghost.ApplyAction
        input: ActionTurn
