/* Optional haunted illumination: slow, low contrast, never a strobe. */
.clue-controls {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 14px 24px;
  padding: 10px 20px;
  border-top: 1px solid var(--line);
  color: var(--mint);
  font: 10px var(--mono);
  letter-spacing: 0.06em;
}
.clue-controls label {
  display: flex;
  align-items: center;
  gap: 7px;
  cursor: pointer;
}
.clue-controls input {
  -webkit-appearance: none;
  appearance: none;
  display: inline-grid;
  place-content: center;
  flex: 0 0 16px;
  width: 16px;
  height: 16px;
  min-width: 16px;
  min-height: 16px;
  padding: 0;
  margin: 0;
  accent-color: #a4ffe0;
  border: 1px solid #608c86;
  border-radius: 2px;
  background: #101b22;
  cursor: pointer;
}
.clue-controls input:checked {
  background: var(--mint);
  border-color: var(--mint);
}
.clue-controls input::after {
  content: "";
  width: 8px;
  height: 4px;
  border-left: 2px solid #0b1817;
  border-bottom: 2px solid #0b1817;
  transform: translateY(-1px) rotate(-45deg);
  opacity: 0;
}
.clue-controls input:checked::after {
  opacity: 1;
}
.clue-controls input:disabled {
  opacity: 0.4;
  cursor: default;
}
#maze:focus-visible {
  outline: 2px solid var(--pink);
  outline-offset: -3px;
}
.clue-controls button {
  padding: 7px 10px;
  font-size: 10px;
}
.viewport[data-haunting="FAINT"] {
  --haunt-alpha: 0.06;
}
.viewport[data-haunting="NOTICEABLE"] {
  --haunt-alpha: 0.1;
}
.viewport[data-haunting="STRONG"] {
  --haunt-alpha: 0.16;
}
.viewport[data-haunting="INTENSE"] {
  --haunt-alpha: 0.23;
}
.viewport[data-haunting]:not([data-haunting=""])::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  animation: haunted-breath 4s ease-in-out infinite;
}
.viewport.exit-seen {
  outline: 1px solid #c0ffe0;
  outline-offset: -2px;
}
@keyframes haunted-breath {
  0%,
  100% {
    box-shadow: inset 0 0 24px rgba(125, 255, 210, var(--haunt-alpha));
  }
  50% {
    box-shadow: inset 0 0 42px rgba(125, 255, 210, var(--haunt-alpha));
  }
}
@media (prefers-reduced-motion: reduce) {
  .viewport[data-haunting]:not([data-haunting=""])::before {
    animation: none;
    box-shadow: inset 0 0 25px rgba(125, 255, 210, var(--haunt-alpha));
  }
}
